// 2026-08-25 修復：真實訊息body會包一層信封，例如
// "[Telegram coach id:6124913915 +13m Tue 2026-08-25 13:50:26 GMT+8] coach: 總結，總結一下。"
// （查inbound_echo log證實這是真實格式，見試金石對應記憶）。原本的TRIGGER_RE要求字串
// 開頭就是「總結」，導致真實訊息完全不會觸發——本場教練說「總結，總結一下」時這支hook
// 完全沒反應，一路查log才抓到這個信封格式問題。
function stripEnvelope(raw) {
  const idx = raw.lastIndexOf(']');
  let body = idx >= 0 ? raw.slice(idx + 1) : raw;
  body = body.replace(/^\s*[^\[\]:]{1,30}:\s*/, ''); // 去掉「coach: 」這類寄件人標籤
  return body.trim();
}

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    c.body, c.bodyForAgent,
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  for (const v of cands) if (typeof v === 'string' && v.trim()) return stripEnvelope(v);
  return '';
}

