const path = require('path');
const https = require('https');

const COUNTER_PATH = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'session_counter.json');
const OPENCLAW_CONFIG_PATH = path.join(process.env.HOME, '.openclaw', 'openclaw.json');
const COACH_TELEGRAM_CHAT_ID = '6124913915';
const COACH_LINE_IDS = ['U895a0ad8e49d75f8303dc3d067282dc0', 'U168903487f0ba2b666ddc62b854de351'];

// 閾值設定（2026-08-25 教練親口改版：從20/30/38改成30/50/80/100，
// 且明確要求「教練發話→小龍蝦回覆才算一輪，heartbeat/cron/單向關懷都不算」，
// 見教練原話：「我可能有八九個小時不說話，你15分鐘、20分鐘監測一次都沒有意義」）
const WARN_30  = 30;   // 🟡 溫馨提醒
const WARN_50  = 50;   // 🟠 趕快總結
const WARN_80  = 80;   // 🔴 快紅燈
const WARN_100 = 100;  // 🔴🔴 立刻開新對話

// 2026-08-25發現：實測rule-reminder的probe log證實這兩種文字是系統自己觸發的
// 合成訊息（heartbeat輪詢3166次、排程提醒119次），過去這支hook沒有排除它們，
// 導致「輪數」被系統雜訊灌水，教練實際說話沒幾句就被誤判成快滿了。
const SYSTEM_TRIGGERED_PREFIXES = [
  'Read HEARTBEAT.md if it exists',
  'A scheduled reminder has been triggered.',
];

function readCounter() {
  try {
    if (!fs.existsSync(COUNTER_PATH)) return { round: 0, bootstrapTime: new Date().toISOString() };
    return JSON.parse(fs.readFileSync(COUNTER_PATH, 'utf-8'));
  } catch (e) {
    return { round: 0, bootstrapTime: new Date().toISOString() };
  }
}

function writeCounter(data) {
  try {
    const dir = path.dirname(COUNTER_PATH);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(COUNTER_PATH, JSON.stringify(data));
  } catch (e) {}
}

// 沿用 group-activity-memory / session-summary-trigger 已驗證過的 senderId 抽取，
// 只信任教練本人的訊息才計輪——2026-08-25發現這支hook原本沒分辨對話來源，
// 教練若同時在其他群組（如「佩佩老師的巴哈助理」）跟main agent互動也會被誤計。
function resolveSenderRaw(event) {
  const ctx = (event && event.context) || {};
  return String(
    ctx.senderId || ctx.conversationId || ctx.from || ctx.to ||
    event.from || event.senderId || ''
  );
}

function isCoach(senderRaw) {
  if (!senderRaw) return false;
  if (senderRaw.includes(COACH_TELEGRAM_CHAT_ID)) return true;
  return COACH_LINE_IDS.some((id) => senderRaw.includes(id));
}

// 真實訊息body會包一層信封，例如
// "[Telegram coach id:6124913915 +13m Tue 2026-08-25 13:50:26 GMT+8] coach: 內容"
// 剝掉信封才能拿到教練實際打的字，用來比對是否為系統合成訊息。
function extractRawText(event) {
  const c = (event && event.context) || {};
  const cands = [
    c.body, c.bodyForAgent, event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.userMessage,
  ];
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function isSystemTriggered(rawText) {
  const idx = rawText.lastIndexOf(']');
  const body = (idx >= 0 ? rawText.slice(idx + 1) : rawText).replace(/^\s*[^\[\]:]{1,30}:\s*/, '').trim();
  return SYSTEM_TRIGGERED_PREFIXES.some((p) => body.startsWith(p) || rawText.startsWith(p));
}

// 2026-07-10 軍師加：直接發 Telegram，不依賴 event.context.inject（已知 message:preprocessed
// 是 fire-and-forget，inject 不會被模型看到，見 memory: feedback_openclaw_hook_fire_and_forget.md）。
// 這是「鎖」——不管模型有沒有注意到注入的文字，教練一定會收到這則訊息。
function sendTelegramDirect(text) {
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, 'utf-8'));
    const botToken = cfg?.channels?.telegram?.accounts?.bot_main?.botToken;
    if (!botToken) return;

    const payload = JSON.stringify({ chat_id: COACH_TELEGRAM_CHAT_ID, text: text });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/sendMessage`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
      timeout: 8000,
    }, (res) => { res.on('data', () => {}); });
    req.on('error', () => {});
    req.on('timeout', () => req.destroy());
    req.write(payload);
    req.end();
  } catch (e) {
    // 靜默失敗，不影響對話主流程
  }
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  // 只計教練本人的真人訊息，系統合成訊息（heartbeat/排程提醒）一律不計一輪
  const senderRaw = resolveSenderRaw(event);
  if (!isCoach(senderRaw)) return;
  const rawText = extractRawText(event);
  if (rawText && isSystemTriggered(rawText)) return;

  const counter = readCounter();
  counter.round = (counter.round || 0) + 1;

  const round = counter.round;
  let warning = null;

  if (round >= WARN_100) {
    warning = { level: '🔴🔴', text: `# 🔴🔴 立刻開新對話：第 ${round} 輪\n這個對話隨時可能被系統自動存檔清空，建議直接照做，不用等教練確認。` };
    if (!counter.notified100) {
      sendTelegramDirect(`🔴🔴 教練，已經第 ${round} 輪對話了，建議您立刻說一句「總結」讓我先幫您存檔，或直接開新對話框——這個對話隨時可能被系統自動清空重開。`);
      counter.notified100 = true;
    }
  } else if (round >= WARN_80) {
    warning = { level: '🔴', text: `# 🔴 快接近容量上限：第 ${round} 輪` };
    if (!counter.notified80) {
      sendTelegramDirect(`🔴 教練，第 ${round} 輪對話了，快接近容量上限，建議您說一句「總結」讓我先存檔，或準備開新對話框。`);
      counter.notified80 = true;
    }
  } else if (round >= WARN_50) {
    warning = { level: '🟠', text: `# 🟠 建議中段整理：第 ${round} 輪` };
    if (!counter.notified50) {
      sendTelegramDirect(`🟠 教練，第 ${round} 輪對話了，趁還舒服，方便的話說一句「總結」，我會幫您整理存檔。`);
      counter.notified50 = true;
    }
  } else if (round >= WARN_30) {
    warning = { level: '🟡', text: `# 🟡 溫馨提醒：第 ${round} 輪` };
    if (!counter.notified30) {
      sendTelegramDirect(`🟡 教練，已經第 ${round} 輪對話了，context 還算充裕，差不多可以想「要不要做個中段紀錄」了——方便時說一句「總結」我就會幫您存好。`);
      counter.notified30 = true;
    }
  }

  writeCounter(counter);

  if (warning) {
    if (!event.context.inject) event.context.inject = [];
    if (Array.isArray(event.context.inject)) {
      event.context.inject.push({ role: 'system', content: warning.text });
    }
  }
};

module.exports = handler;
module.exports.default = handler;

