"use strict";
// 測試 hooks/context-overflow-guard/handler.js 的2026-08-25改版：
// ①門檻改30/50/80/100 ②只計教練本人真人訊息 ③heartbeat/排程提醒不計輪
// 用暫存counter檔案跑，跑完還原，不影響真實計數狀態。

const fs = require('fs');
const path = require('path');

const HANDLER_PATH = path.join(process.env.HOME, '.openclaw', 'hooks', 'context-overflow-guard', 'handler.js');
const COUNTER_PATH = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'session_counter.json');

function mkEvent({ senderId = 'telegram:direct:6124913915', text = '哈囉' } = {}) {
  return { type: 'message', action: 'preprocessed', context: { senderId, body: text, inject: [] } };
}

function resetCounter() {
  fs.writeFileSync(COUNTER_PATH, JSON.stringify({ round: 0, bootstrapTime: new Date().toISOString() }));
}

function readCounter() {
  return JSON.parse(fs.readFileSync(COUNTER_PATH, 'utf-8'));
}

async function run() {
  // 備份真實counter
  let backup = null;
  try { backup = fs.readFileSync(COUNTER_PATH, 'utf-8'); } catch (e) {}

  delete require.cache[require.resolve(HANDLER_PATH)];
  const handler = require(HANDLER_PATH);
  let pass = 0, fail = 0;

  function check(name, cond) {
    console.log((cond ? '✅' : '❌'), name);
    cond ? pass++ : fail++;
  }

  console.log('=== 系統合成訊息不該計輪 ===');
  resetCounter();
  await handler(mkEvent({ text: 'Read HEARTBEAT.md if it exists (workspace context)' }));
  await handler(mkEvent({ text: '[Telegram coach id:6124913915 Tue 2026-08-25 10:00:00 GMT+8] coach: A scheduled reminder has been triggered. The reminder says...' }));
  check('heartbeat/排程提醒不計輪(round應仍為0)', readCounter().round === 0);

  console.log('=== 非教練訊息不該計輪 ===');
  resetCounter();
  await handler(mkEvent({ senderId: 'telegram:group:-1003537129853', text: '[Telegram 活動討論群] 某人: 大家好' }));
  check('群組其他人發言不計輪', readCounter().round === 0);

  console.log('=== 教練真人訊息應該計輪 ===');
  resetCounter();
  for (let i = 0; i < 29; i++) await handler(mkEvent({ text: `第${i+1}句話` }));
  check('29輪後尚未達30門檻(round=29)', readCounter().round === 29);
  await handler(mkEvent({ text: '第30句話' }));
  const c30 = readCounter();
  check('第30輪 notified30=true', c30.round === 30 && c30.notified30 === true);
  check('第30輪 notified50尚未觸發', !c30.notified50);

  for (let i = 0; i < 19; i++) await handler(mkEvent({ text: '繼續講話' }));
  const c50 = readCounter();
  check('第50輪 notified50=true', c50.round === 50 && c50.notified50 === true);

  for (let i = 0; i < 29; i++) await handler(mkEvent({ text: '繼續講話' }));
  const c79 = readCounter();
  check('第79輪 notified80尚未觸發', c79.round === 79 && !c79.notified80);
  await handler(mkEvent({ text: '第80句' }));
  const c80 = readCounter();
  check('第80輪 notified80=true', c80.round === 80 && c80.notified80 === true);

  for (let i = 0; i < 19; i++) await handler(mkEvent({ text: '繼續講話' }));
  const c99 = readCounter();
  check('第99輪 notified100尚未觸發', c99.round === 99 && !c99.notified100);
  await handler(mkEvent({ text: '第100句' }));
  const c100 = readCounter();
  check('第100輪 notified100=true', c100.round === 100 && c100.notified100 === true);

  console.log('=== 真實信封格式的教練訊息應該正確計輪(不誤判成系統訊息) ===');
  resetCounter();
  await handler(mkEvent({ text: '[Telegram coach id:6124913915 +13m Tue 2026-08-25 13:50:26 GMT+8] coach: 總結，總結一下。' }));
  check('真實信封格式教練訊息有計輪', readCounter().round === 1);

  // 還原真實counter
  if (backup !== null) fs.writeFileSync(COUNTER_PATH, backup);
  else fs.unlinkSync(COUNTER_PATH);

  console.log('\n' + (fail === 0 ? '🎉 全部通過' : '⚠️ 有失敗') + ` (${pass} pass / ${fail} fail)`);
  process.exit(fail === 0 ? 0 : 1);
}

run();

