  await handler(mkEvent({ text: '[Telegram coach id:6124913915 +13m Tue 2026-08-25 13:50:26 GMT+8] coach: 總結，總結一下。' }));
  check('真實信封格式教練訊息有計輪', readCounter().round === 1);

  // 還原真實counter
  if (backup !== null) fs.writeFileSync(COUNTER_PATH, backup);
  else fs.unlinkSync(COUNTER_PATH);

  check('確認Telegram發送已被攔截，非真的發出(應為4次:30/50/80/100各一次)', sentCount === 4);

  console.log('\n' + (fail === 0 ? '🎉 全部通過' : '⚠️ 有失敗') + ` (${pass} pass / ${fail} fail)`);
  process.exit(fail === 0 ? 0 : 1);
}

