"use strict";

// OpenClaw Hook：line-url-typo-guard
// 用途：bni_tainan 送出前自動校正常見網址手滑錯字，避免會員點到404；
//       累計滿3的倍數次自動通知教練，不用多買備援網址救援。
// 事件：message:sending（送出前，可改寫 content）
// 軍師建立 2026-07-24（教練回報培訓連結404 + 明確指示「手滑不能叫我多買網址，重複3次要徹底解決」）

const fs = require('fs');
const path = require('path');
const https = require('https');

const HOME = process.env.HOME;
const STATE_FILE = path.join(HOME, '.openclaw', 'workspace', 'state', 'line_url_typo_guard.json');
const OPENCLAW_CONFIG = path.join(HOME, '.openclaw', 'openclaw.json');
const COACH_CHAT_ID = '6124913915';

// 已知正確網址 → 比對其常見手滑變體的 regex（漏連字號、calender/calendar混淆）
const KNOWN_URLS = [
  {
    correct: 'https://tainan-calender.netlify.app/',
    // 比對 tainan(-)?calend(e|a)r.netlify.app，任何非完全正確寫法都算命中
    pattern: /tainan-?calend[ae]r\.netlify\.app\/?/gi,
    correctBare: 'tainan-calender.netlify.app/',
  },
];

function loadState() {
  try {
    return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  } catch (e) {
    return { count: 0, lastNotifiedAt: null, events: [] };
  }
}

function saveState(state) {
  try {
    fs.mkdirSync(path.dirname(STATE_FILE), { recursive: true });
    fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));
  } catch (e) { /* silent */ }
}

function notifyCoach(message) {
  try {
    const raw = fs.readFileSync(OPENCLAW_CONFIG, 'utf8');
    const cfg = JSON.parse(raw);
    const token = cfg?.channels?.telegram?.accounts?.bot_main?.botToken;
    if (!token) return;
    const body = JSON.stringify({ chat_id: COACH_CHAT_ID, text: message });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${token}/sendMessage`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
    });
    req.on('error', () => {});
    req.write(body);
    req.end();
  } catch (e) { /* silent */ }
}

function isBniTainanLine(event, ctx) {
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const channel = String(event.channel ?? ctx.channel ?? '');
  const accountId = String(event.accountId ?? ctx.accountId ?? '');
  if (sessionKey.includes('bni_tainan') && sessionKey.includes('line')) return true;
  if (channel === 'line' && accountId === 'bni_tainan') return true;
  return false;
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'sending') return;

  const ctx = event.context ?? {};
  if (!isBniTainanLine(event, ctx)) return;

  let content = event.content ?? ctx.content;
  if (typeof content !== 'string' || !content) return;

  let changed = false;
  const hits = [];

  for (const spec of KNOWN_URLS) {
    content = content.replace(spec.pattern, (match) => {
      if (match.toLowerCase() === spec.correctBare.toLowerCase()) return match; // 本來就對，不動
      hits.push({ wrong: match, correct: spec.correct });
      changed = true;
      return spec.correct.replace(/^https?:\/\//, '');
    });
  }

  if (!changed) return;

  const state = loadState();
  state.count += 1;
  state.events = (state.events || []).slice(-19).concat([{
    ts: new Date().toISOString(),
    hits,
  }]);

  if (state.count % 3 === 0) {
    notifyCoach(
      `🔗 大台南小幫手網址手滑偵測：累計已修正 ${state.count} 次` +
      `（最新一次：${hits.map(h => h.wrong).join(', ')} → ${hits.map(h => h.correct).join(', ')}）。` +
      `已達3次門檻，這不是靠備援網址能解決的，需要軍師分析根因、調整提示詞。`
    );
    state.lastNotifiedAt = new Date().toISOString();
  }

  saveState(state);

  return { content };
};

module.exports = handler;
module.exports.default = handler;

"use strict";

const fs = require("fs");
const path = require("path");
const https = require("https");
const { spawn } = require("child_process");

const NAMECARD_FOLDER = "/Volumes/home/名片媒合中心";
const NAMECARD_DB_DIR = path.join(process.env.HOME, ".openclaw", "workspace", "namecard-db");
const NAMECARD_PYTHON = path.join(NAMECARD_DB_DIR, "venv", "bin", "python3");
const STATE_PATH = path.join(process.env.HOME, ".openclaw", "hooks", "namecard-inbound", "processed.json");
const LOG_PATH = path.join(process.env.HOME, ".openclaw", "hooks", "namecard-inbound", "inbound.log");
const OPENCLAW_CONFIG_PATH = path.join(process.env.HOME, ".openclaw", "openclaw.json");
const COACH_TELEGRAM_CHAT_ID = "6124913915";
const MAX_PROCESSED = 200;

const IMAGE_EXTS = new Set([".jpg", ".jpeg", ".png", ".heic", ".heif", ".webp"]);

function log(line) {
  try {
    fs.appendFileSync(LOG_PATH, `[${new Date().toISOString()}] ${line}\n`);
  } catch (e) {
    // ignore
  }
}

function readProcessed() {
  try {
    if (!fs.existsSync(STATE_PATH)) return [];
    return JSON.parse(fs.readFileSync(STATE_PATH, "utf-8"));
  } catch (e) {
    return [];
  }
}

function writeProcessed(list) {
  try {
    fs.mkdirSync(path.dirname(STATE_PATH), { recursive: true });
    fs.writeFileSync(STATE_PATH, JSON.stringify(list.slice(-MAX_PROCESSED)));
  } catch (e) {
    // ignore
  }
}

function isImage(mediaPath, mediaType) {
  if (mediaType && String(mediaType).toLowerCase().startsWith("image/")) return true;
  const ext = path.extname(mediaPath || "").toLowerCase();
  return IMAGE_EXTS.has(ext);
}

function hasTrigger(text) {
  return typeof text === "string" && text.includes("名片");
}

function sendTelegramDirect(text) {
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, "utf-8"));
    const botToken = cfg?.channels?.telegram?.accounts?.bot_main?.botToken;
    if (!botToken) return;

    const payload = JSON.stringify({ chat_id: COACH_TELEGRAM_CHAT_ID, text });
    const req = https.request(
      {
        hostname: "api.telegram.org",
        path: `/bot${botToken}/sendMessage`,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(payload),
        },
        timeout: 8000,
      },
      (res) => {
        res.on("data", () => {});
      }
    );
    req.on("error", () => {});
    req.on("timeout", () => req.destroy());
    req.write(payload);
    req.end();
  } catch (e) {
    // 靜默失敗，不影響對話主流程
  }
}

function loadNamecardEnv() {
  // watch_and_extract.py 需要的 ANTHROPIC_API_KEY / NAMECARD_FOLDER 等變數只存在
  // namecard-db/.env（shell export格式），這支hook是獨立spawn出去的子行程，
  // 不會自動繼承，要自己讀進來塞進spawn的env，不然子行程會因為缺變數直接失敗。
  const envPath = path.join(NAMECARD_DB_DIR, ".env");
  const merged = { ...process.env };
  try {
    const content = fs.readFileSync(envPath, "utf-8");
    for (const line of content.split("\n")) {
      const m = line.match(/^export\s+([A-Z_]+)="(.*)"\s*$/);
      if (m) merged[m[1]] = m[2];
    }
  } catch (e) {
    log(`TRIGGER 讀不到.env: ${e && e.message}`);
  }
  return merged;
}

function triggerExtractOnce() {
  try {
    const logFd = fs.openSync(path.join(NAMECARD_DB_DIR, "watch.log"), "a");
    const child = spawn(NAMECARD_PYTHON, ["watch_and_extract.py", "--once"], {
      cwd: NAMECARD_DB_DIR,
      env: loadNamecardEnv(),
      detached: true,
      stdio: ["ignore", logFd, logFd],
    });
    child.unref();
    log(`TRIGGER 已叫辨識程式立刻跑一次（PID ${child.pid}），事件觸發，沒有背景排程`);
  } catch (e) {
    log(`TRIGGER 啟動失敗: ${e && e.message}`);
  }
}

function timestampSlug() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}

const handler = async (event) => {
  if (!event || typeof event !== "object") return;
  if (event.type !== "message" || event.action !== "preprocessed") return;
  if (!event.context || typeof event.context !== "object") return;

  const ctx = event.context;
  const mediaPath = ctx.mediaPath;
  const mediaType = ctx.mediaType;
  const text = ctx.bodyForAgent || ctx.body || "";

  if (!mediaPath) return;
  if (!isImage(mediaPath, mediaType)) return;
  if (!hasTrigger(text)) return;

  // 冪等：同一則訊息（mediaPath+messageId）不重複處理
  const dedupeKey = `${ctx.messageId || ""}:${mediaPath}`;
  const processed = readProcessed();
  if (processed.includes(dedupeKey)) return;

  try {
    if (!fs.existsSync(mediaPath)) {
      log(`SKIP 來源檔案不存在: ${mediaPath}`);
      return;
    }
    if (!fs.existsSync(NAMECARD_FOLDER)) {
      log(`FAIL 目的資料夾不存在（Amber SMB可能沒掛載）: ${NAMECARD_FOLDER}`);
      sendTelegramDirect(
        `🔴 教練，收到您傳的名片照片，但無法存進辨識資料夾（Amber私有雲可能斷線），請檢查 SMB 連線。原始照片仍在：${mediaPath}`
      );
      return;
    }

    const ext = path.extname(mediaPath) || ".jpg";
    const channel = ctx.channelId || "unknown";
    const destName = `${timestampSlug()}-${channel}${ext}`;
    const destPath = path.join(NAMECARD_FOLDER, destName);

    fs.copyFileSync(mediaPath, destPath);
    log(`OK 複製成功: ${mediaPath} -> ${destPath}（來源頻道: ${channel}）`);

    processed.push(dedupeKey);
    writeProcessed(processed);

    triggerExtractOnce();
  } catch (e) {
    log(`FAIL 複製失敗: ${e && e.message}`);
    sendTelegramDirect(`🔴 教練，收到您傳的名片照片，但轉存失敗：${e && e.message}。原始照片仍在：${mediaPath}`);
  }
};

module.exports = handler;
module.exports.default = handler;

